{"code": "import pytest
import impl


def test_basic_usd():
    """Basic USD formatting with 2 decimals."""
    exponents = {"USD": 2}
    assert impl.format_amount("123.45", "USD", exponents) == "123.45"


def test_jpy_zero_decimals():
    """JPY (exponent 0) has no decimal point."""
    exponents = {"JPY": 0}
    assert impl.format_amount("1234.5", "JPY", exponents) == "1234"


def test_multiple_exponents():
    """Different currencies with different exponents."""
    exponents = {"KWD": 3, "CLF": 4}
    assert impl.format_amount("1.234", "KWD", exponents) == "1.234"
    assert impl.format_amount("12.3456", "CLF", exponents) == "12.3456"


def test_round_half_even_up():
    """2.675 USD rounds to 2.68 (banker's rounding)."""
    exponents = {"USD": 2}
    assert impl.format_amount("2.675", "USD", exponents) == "2.68"


def test_round_half_even_down():
    """2.665 USD rounds to 2.66 (banker's rounding)."""
    exponents = {"USD": 2}
    assert impl.format_amount("2.665", "USD", exponents) == "2.66"


def test_negative_rounding():
    """Negative amounts round symmetrically."""
    exponents = {"USD": 2}
    assert impl.format_amount("-2.675", "USD", exponents) == "-2.68"


def test_amount_parsing():
    """Amount parsing handles whitespace, signs, scientific notation."""
    exponents = {"USD": 2}
    assert impl.format_amount("  123.45  ", "USD", exponents) == "123.45"
    assert impl.format_amount("-123.45", "USD", exponents) == "-123.45"
    assert impl.format_amount("+123.45", "USD", exponents) == "123.45"
    assert impl.format_amount("1E+2", "USD", exponents) == "100.00"


def test_decimal_place_adjustment():
    """Padding and truncating decimals."""
    exponents = {"USD": 2}
    assert impl.format_amount("123.456789", "USD", exponents) == "123.46"
    assert impl.format_amount("123.4", "USD", exponents) == "123.40"
    assert impl.format_amount("123", "USD", exponents) == "123.00"


def test_zero_handling():
    """Zero is always unsigned, no decimal point for exponent 0."""
    exponents = {"USD": 2, "JPY": 0}
    assert impl.format_amount("-0.004", "USD", exponents) == "0.00"
    assert impl.format_amount("-1.5e-3", "USD", exponents) == "0.00"
    assert impl.format_amount("0", "JPY", exponents) == "0"


def test_unknown_currency():
    """Unknown currency raises KeyError."""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("123.45", "XXX", exponents)


def test_currency_lookup_first():
    """Currency lookup happens before amount validation."""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("invalid_amount", "ZZZ", exponents)


def test_invalid_amount():
    """Invalid amounts raise ValueError."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("", "USD", exponents)
    with pytest.raises(ValueError):
        impl.format_amount("abc", "USD", exponents)
    with pytest.raises(ValueError):
        impl.format_amount("1.2.3", "USD", exponents)


def test_non_finite():
    """Non-finite values raise ValueError."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("Infinity", "USD", exponents)
    with pytest.raises(ValueError):
        impl.format_amount("NaN", "USD", exponents)


def test_no_formatting_artifacts():
    """No thousands separators, no + sign, no symbol."""
    exponents = {"USD": 2}
    result = impl.format_amount("999999999999.99", "USD", exponents)
    assert result == "999999999999.99"
    assert "," not in result
    assert "$" not in result
    assert "+" not in result


def test_scientific_notation_large():
    """Large scientific notation is expanded."""
    exponents = {"USD": 2}
    assert impl.format_amount("1E+10", "USD", exponents) == "10000000000.00"


def test_negative_with_rounding():
    """Negative amounts with rounding work correctly."""
    exponents = {"USD": 2}
    assert impl.format_amount("-123.456789", "USD", exponents) == "-123.46"
"}
